const similarHooks = `-- name: SimilarHooks :many
SELECT id, text, (1 - (embedding <=> $2))::float8 AS similarity
FROM hooks
WHERE project_id = $1 AND embedding IS NOT NULL
ORDER BY embedding <=> $2
LIMIT $3
`

type SimilarHooksParams struct {
	ProjectID int64
	Embedding *pgvector_go.Vector
	Limit     int32
}

type SimilarHooksRow struct {
	ID         int64
	Text       string
	Similarity float64
}

// Deleted hooks count: a deleted idea must not come back.
func (q *Queries) SimilarHooks(ctx context.Context, arg SimilarHooksParams) ([]SimilarHooksRow, error) {
	rows, err := q.db.Query(ctx, similarHooks, arg.ProjectID, arg.Embedding, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SimilarHooksRow
	for rows.Next() {
		var i SimilarHooksRow
		if err := rows.Scan(&i.ID, &i.Text, &i.Similarity); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

